-- Portable structural fingerprints: role names, no project-specific object OIDs.
-- No table records, Auth configuration or credentials are returned.
with scopes(scope,names) as (values
 ('application',array['public','audit','supabase_migrations']::text[]),
 ('managed',array['auth','storage']::text[])
), catalogs as (
 select scope,jsonb_build_object(
 'columns',(select jsonb_agg(to_jsonb(a) order by a.table_schema,a.table_name,a.ordinal_position) from information_schema.columns a where a.table_schema=any(s.names)),
 'column_acl',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attname,(select jsonb_agg(jsonb_build_array(pg_get_userbyid(x.grantor),case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,x.privilege_type,x.is_grantable) order by x.grantor::regrole::text,x.grantee::regrole::text,x.privilege_type) from aclexplode(a.attacl) x)) order by n.nspname,c.relname,a.attname) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(s.names) and not a.attisdropped and a.attnum>0 and cardinality(a.attacl)>0),
 'role_capabilities',case when scope='application' then (select jsonb_agg(jsonb_build_array(r.rolname,r.rolsuper,r.rolinherit,r.rolcreaterole,r.rolcreatedb,r.rolcanlogin,r.rolreplication,r.rolbypassrls,r.rolconnlimit,(select jsonb_agg(x order by x) from unnest(r.rolconfig) x)) order by r.rolname) from pg_roles r) end,
 'role_memberships',case when scope='application' then (select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.roleid),pg_get_userbyid(a.member),pg_get_userbyid(a.grantor),a.admin_option,a.inherit_option,a.set_option) order by pg_get_userbyid(a.roleid),pg_get_userbyid(a.member),pg_get_userbyid(a.grantor)) from pg_auth_members a) end,
 'parameter_acl',case when scope='application' then (select jsonb_agg(jsonb_build_array(p.parname,(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by pg_get_userbyid(a.grantor),pg_get_userbyid(a.grantee),a.privilege_type) from aclexplode(p.paracl) a)) order by p.parname) from pg_parameter_acl p) end,
 'custom_types',(select jsonb_agg(jsonb_build_array(n.nspname,t.typname,t.typtype,pg_get_userbyid(t.typowner),t.typnotnull,t.typdefault,format_type(t.typbasetype,t.typtypmod),t.typcollation::regcollation::text,t.typacl::text,(select jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.contypid=t.oid),(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attcollation::regcollation::text) order by a.attnum) from pg_attribute a where a.attrelid=t.typrelid and a.attnum>0 and not a.attisdropped),(select jsonb_build_array(r.rngsubtype::regtype::text,r.rngcollation::regcollation::text,onsp.nspname,o.opcname,r.rngcanonical::regproc::text,r.rngsubdiff::regproc::text) from pg_range r join pg_opclass o on o.oid=r.rngsubopc join pg_namespace onsp on onsp.oid=o.opcnamespace where r.rngtypid=t.oid)) order by n.nspname,t.typname) from pg_type t join pg_namespace n on n.oid=t.typnamespace left join pg_class c on c.oid=t.typrelid where n.nspname=any(s.names) and (t.typtype in ('d','e','r','m') or t.typtype='c' and c.relkind='c')),
 'relations',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,c.relkind,pg_get_userbyid(c.relowner),c.relrowsecurity,c.relforcerowsecurity,c.reloptions,obj_description(c.oid,'pg_class'),(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantor::regrole::text,a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) a)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(s.names) and c.relkind in ('r','p','S','v','m')),
 'constraints',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,k.conname,pg_get_constraintdef(k.oid),k.convalidated,k.condeferrable,k.condeferred) order by n.nspname,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname=any(s.names)),
 'functions',(select jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proconfig,p.prosecdef,(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantor::regrole::text,a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) order by n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname=any(s.names) and p.prokind in ('f','p')),
 'triggers',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,t.tgname,pg_get_triggerdef(t.oid),t.tgenabled) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname=any(s.names)),
 'policies',(select jsonb_agg(to_jsonb(p) order by p.schemaname,p.tablename,p.policyname) from pg_policies p where p.schemaname=any(s.names)),
 'schemas',(select jsonb_agg(jsonb_build_array(n.nspname,pg_get_userbyid(n.nspowner),(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.grantor),case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,a.privilege_type,a.is_grantable) order by a.grantor::regrole::text,a.grantee::regrole::text,a.privilege_type) from aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a)) order by n.nspname) from pg_namespace n where n.nspname=any(s.names)),
 'default_acl',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(a.defaclrole),n.nspname,a.defaclobjtype,(select jsonb_agg(jsonb_build_array(pg_get_userbyid(x.grantor),case when x.grantee=0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end,x.privilege_type,x.is_grantable) order by x.grantor::regrole::text,x.grantee::regrole::text,x.privilege_type) from aclexplode(a.defaclacl) x)) order by pg_get_userbyid(a.defaclrole),n.nspname,a.defaclobjtype) from pg_default_acl a left join pg_namespace n on n.oid=a.defaclnamespace where n.nspname=any(s.names) or scope='application' and a.defaclnamespace=0),
 'views',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_viewdef(c.oid)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('v','m') and n.nspname=any(s.names)),
 'indexes',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,pg_get_indexdef(c.oid)) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind in ('i','I') and n.nspname=any(s.names)),
 'sequences',(select jsonb_agg(to_jsonb(q)-'last_value' order by q.schemaname,q.sequencename) from pg_sequences q where q.schemaname=any(s.names)),
 'enums',(select jsonb_agg(jsonb_build_array(n.nspname,t.typname,e.enumsortorder,e.enumlabel) order by n.nspname,t.typname,e.enumsortorder) from pg_enum e join pg_type t on t.oid=e.enumtypid join pg_namespace n on n.oid=t.typnamespace where n.nspname=any(s.names))
 ) as value from scopes s
)
select jsonb_object_agg(scope,encode(extensions.digest(value::text,'sha256'),'hex')) as catalog from catalogs;
